def dependency_stages(deps):
    waiting = {job: set(required) for job, required in deps.items()}
    for required in waiting.values():
        if required.difference(waiting):
            raise ValueError("unknown prerequisite")
    stages = []
    while waiting:
        stage = tuple(sorted(job for job, required in waiting.items() if not required))
        if not stage:
            raise ValueError("cyclic jobs")
        stages.append(stage)
        for job in stage:
            del waiting[job]
        for required in waiting.values():
            required.difference_update(stage)
    return stages

def daily_counters(rows):
    result = {}
    for day, name, delta in rows:
        if not isinstance(day, str) or not day or not isinstance(name, str) or not name or type(delta) is not int:
            raise ValueError("invalid row")
        current = result.setdefault(day, {})
        current[name] = current.get(name, 0) + delta
    return result

def collapse_runs(values, maximum):
    if type(maximum) is not int or maximum < 1:
        raise ValueError("invalid maximum")
    result = []
    for value in values:
        if not isinstance(value, str):
            raise ValueError("invalid value")
        if result and result[-1][0] == value and result[-1][1] < maximum:
            result[-1] = (value, result[-1][1] + 1)
        else:
            result.append((value, 1))
    return result

def transfer_stock(inventory, moves):
    result = dict(inventory)
    for key, balance in result.items():
        if not isinstance(key, str) or not key or type(balance) is not int or balance < 0:
            raise ValueError("invalid inventory")
    for source, target, quantity in moves:
        if not isinstance(source, str) or not isinstance(target, str) or source == target or source not in result or target not in result:
            raise ValueError("invalid transfer")
        if type(quantity) is not int or quantity <= 0 or result[source] < quantity:
            raise ValueError("invalid quantity")
        result[source] -= quantity
        result[target] += quantity
    return result
